import React, { useState } from 'react';
import { Menu, X, Home, ChevronDown } from 'lucide-react';
import collegeLogo from '../../assets/cec122.png';

const navItems = [
    { name: 'HOME', path: '#home', hasDropdown: false, isHome: true },
    { name: 'ABOUT', path: '#about', hasDropdown: false },
    { 
        name: 'ADMINISTRATION', path: '#administration', hasDropdown: true, 
        dropdownItems: [
            { label: 'Principal', path: '#principal' },
            { label: 'Deans', path: '#deans' },
            { label: 'Staff Directory', path: '#staff' }
        ]
    },
    { 
        name: 'ACADEMICS', path: '#academics', hasDropdown: true,
        dropdownItems: [
            { label: 'Departments', path: '#departments' },
            { label: 'Programs Offered', path: '#programs' },
            { label: 'Syllabus', path: '#syllabus' }
        ]
    },

    {
        name: 'PLACEMENT', path: '#placement', hasDropdown: true,
        dropdownItems: [
            { label: 'Placement Cell', path: '#placement-cell' },
            { label: 'Statistics', path: '#statistics' },
            { label: 'Top Recruiters', path: '#recruiters' }
        ]
    },
    {
        name: 'EXAMINATION', path: '#examination', hasDropdown: true,
        dropdownItems: [
            { label: 'Result Portal', path: '#results' },
            { label: 'Timetable', path: '#timetable' },
            { label: 'Notifications', path: '#notifications' }
        ]
    },
    {
        name: 'FACILITIES', path: '#facilities', hasDropdown: true,
        dropdownItems: [
            { label: 'Central Library', path: '#library' },
            { label: 'Laboratories', path: '#labs' },
            { label: 'Hostel & Mess', path: '#hostel' }
        ]
    },
    {
        name: 'CAMPUS', path: '#campus', hasDropdown: true,
        dropdownItems: [
            { label: 'Campus Map', path: '#campus-map' },
            { label: 'Canteen', path: '#canteen' },
            { label: 'Transport', path: '#transport' }
        ]
    },
    {
        name: 'QUICK LINKS', path: '#quick', hasDropdown: true,
        dropdownItems: [
            { label: 'Anti-Ragging', path: '#anti-ragging' },
            { label: 'Grievance Cell', path: '#grievance' },
            { label: 'Tenders', path: '#tenders' }
        ]
    },

    {
        name: 'ACHIEVEMENTS', path: '#achievements', hasDropdown: true,
        dropdownItems: [
            { label: 'Student Awards', path: '#student-awards' },
            { label: 'Faculty Awards', path: '#faculty-awards' },
            { label: 'Patents', path: '#patents' }
        ]
    },
    {
        name: 'ORGANISATIONS', path: '#organisations', hasDropdown: true,
        dropdownItems: [
            { label: 'NSS', path: '#nss' },
            { label: 'IEEE Student Branch', path: '#ieee' },
            { label: 'IEDC', path: '#iedc' }
        ]
    },
    {
        name: 'CONTACT', path: '#contact', hasDropdown: true,
        dropdownItems: [
            { label: 'Reach Us', path: '#reach-us' },
            { label: 'Directory', path: '#directory' },
            { label: 'Feedback', path: '#feedback' }
        ]
    }
];

const NavItem = ({ item, closeMobileMenu }) => {
    const [isMobileExpanded, setIsMobileExpanded] = useState(false);

    if (!item.hasDropdown) {
        return (
            <li>
                <a 
                    href={item.path} 
                    onClick={closeMobileMenu} 
                    className="flex items-center gap-1 block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 hover:text-gold md:py-[14px]"
                >
                    {item.isHome && <Home size={18} />} {item.name}
                </a>
            </li>
        );
    }

    return (
        <li className="relative group">
            {/* Desktop link rendering: acts as hover trigger and is clickable */}
            <a 
                href={item.path}
                className="hidden md:flex items-center gap-1 whitespace-nowrap px-4 py-[14px] transition hover:bg-coral2 hover:text-gold cursor-pointer"
            >
                {item.name}
                <ChevronDown size={14} className="group-hover:rotate-180 transition-transform duration-300" />
            </a>

            {/* Mobile rendering: separate text (navigates) and chevron (expands list) */}
            <div className="md:hidden flex items-center justify-between px-4 py-3 transition hover:bg-coral2 hover:text-gold">
                <a 
                    href={item.path} 
                    onClick={closeMobileMenu} 
                    className="flex-grow whitespace-nowrap font-semibold tracking-[0.03em]"
                >
                    {item.name}
                </a>
                <button 
                    onClick={(e) => { e.preventDefault(); setIsMobileExpanded(!isMobileExpanded); }} 
                    className="p-1 min-w-[32px] flex justify-end"
                >
                    <ChevronDown size={18} className={`transition transform duration-300 ${isMobileExpanded ? 'rotate-180' : ''}`} />
                </button>
            </div>

            {/* Desktop Dropdown (Hover) */}
            <div className="hidden md:block absolute top-[100%] left-0 bg-coral shadow-[0_10px_30px_rgba(0,0,0,0.15)] min-w-[220px] z-[1000] border-t-2 border-gold rounded-b-md opacity-0 invisible group-hover:opacity-100 group-hover:visible group-hover:block transition-all duration-300 ease-in-out transform origin-top group-hover:translate-y-0 translate-y-2">
                <ul className="flex flex-col py-2">
                    {item.dropdownItems.map((subItem, idx) => (
                        <li key={idx}>
                            <a 
                                href={subItem.path} 
                                onClick={closeMobileMenu} 
                                className="block px-6 py-2.5 hover:bg-coral2 hover:text-gold transition text-[0.95rem] font-medium tracking-wide text-white/95"
                            >
                                {subItem.label}
                            </a>
                        </li>
                    ))}
                </ul>
            </div>

            {/* Mobile Dropdown (Accordion) */}
            <div className={`md:hidden overflow-hidden transition-all duration-300 ease-in-out ${isMobileExpanded ? 'max-h-[500px]' : 'max-h-0'}`}>
                <ul className="bg-coral2 flex flex-col">
                    {item.dropdownItems.map((subItem, idx) => (
                        <li key={idx} className="border-b border-coral/20 border-solid last:border-b-0">
                            <a 
                                href={subItem.path} 
                                onClick={closeMobileMenu} 
                                className="block px-8 py-3 hover:text-gold text-slate-300 transition text-[0.9rem] font-medium tracking-wide"
                            >
                                • {subItem.label}
                            </a>
                        </li>
                    ))}
                </ul>
            </div>
        </li>
    );
};

const Navbar = () => {
    const [isOpen, setIsOpen] = useState(false);

    const closeMobileMenu = () => setIsOpen(false);

    return (
        <nav className="sticky top-0 z-[999] shadow-[0_2px_20px_rgba(10,22,40,0.08)]">
            {/* Top Tier: Logo and College Info */}
            <div className="bg-cream py-3">
                <div className="flex w-full items-center justify-start gap-[20px] px-4 lg:px-8">
                    {/* College Logo */}
                    <img src={collegeLogo} alt="CEC Logo" className="h-[120px] w-[120px] shrink-0 object-contain rounded-sm shadow-sm" />
                    <div className="flex flex-col justify-center text-left">
                        <h1 className="font-display text-[2.2rem] font-extrabold leading-tight text-coral uppercase mb-1 tracking-wide">
                            College Of Engineering Chengannur
                        </h1>
                        <p className="text-[1.1rem] font-bold tracking-[0.02em] text-slate-800">
                            ESTD : 1993 managed by IHRD, A Govt of Kerala Undertaking
                        </p>
                        <p className="text-[1.05rem] font-semibold tracking-[0.02em] text-slate-700 mt-[2px]">
                            Affiliated to A P J Abdul Kalam Technological University, Kerala
                        </p>
                    </div>
                </div>
            </div>

            {/* Bottom Tier: Navigation Links */}
            <div className="bg-coral transition-colors duration-300">
                <div className="relative flex w-full items-center px-4 lg:px-8">
                    <ul
                        className={`${isOpen ? 'flex' : 'hidden'} absolute left-0 top-[100%] w-full flex-col bg-coral py-2 text-[1rem] font-semibold tracking-[0.03em] text-white shadow-[0_15px_30px_rgba(0,0,0,0.15)] md:static md:flex md:w-auto md:flex-row md:py-0 md:shadow-none w-[100%] justify-between flex-wrap`}
                    >
                        {navItems.map((item, index) => (
                            <NavItem key={index} item={item} closeMobileMenu={closeMobileMenu} />
                        ))}
                    </ul>

                    {/* Hamburger Menu Toggle (Mobile) */}
                    <button
                        onClick={() => setIsOpen(!isOpen)}
                        className="ml-auto block p-[10px] text-white md:hidden my-2 border border-white/20 rounded-md hover:bg-white/10 transition"
                        aria-label="Menu"
                    >
                        {isOpen ? <X size={24} /> : <Menu size={24} />}
                    </button>
                </div>
            </div>
        </nav>
    );
};

export default Navbar;
